const BRAND_IMPACT: Record<string, Record<string, WatchtowerApiCell | null>> = {
  corona: {
    impact_pre_period: { value: 82.5, tooltip: '82,500 hl' },
    impact_delta: {
      value: 8.7,
      variation_direction: 'up',
      tooltip: 'Volume Contribution: 1.1%',
    },
    impact_growth_rate: { value: 10.5, variation_direction: 'up' },
    impact_post_period: {
      value: 1.1,
      unit_measure: '%',
      variation_direction: 'up',
    },
  },
  stella: {
    impact_pre_period: { value: 35.8, tooltip: '35,800 hl' },
    impact_delta: {
      value: 3.5,
      variation_direction: 'up',
      tooltip: 'Volume Contribution: 0.5%',
    },
    impact_growth_rate: { value: 9.8, variation_direction: 'up' },
    impact_post_period: {
      value: 0.5,
      unit_measure: '%',
      variation_direction: 'up',
    },
  },
  budweiser: {
    impact_pre_period: { value: 52.3, tooltip: '52,300 hl' },
    impact_delta: {
      value: 11.2,
      variation_direction: 'up',
      tooltip: 'Volume Contribution: 1.6%',
    },
    impact_growth_rate: { value: 21.4, variation_direction: 'up' },
    impact_post_period: {
      value: 1.6,
      unit_measure: '%',
      variation_direction: 'up',
    },
  },
  spaten: {
    impact_pre_period: { value: 38.7, tooltip: '38,700 hl' },
    impact_delta: {
      value: -5.8,
      variation_direction: 'down',
      tooltip: 'Volume Contribution: -0.9%',
    },
    impact_growth_rate: { value: -15, variation_direction: 'down' },
    impact_post_period: {
      value: -0.9,
      unit_measure: '%',
      variation_direction: 'down',
    },
  },
  skol: {
    impact_pre_period: { value: 29.6, tooltip: '29,600 hl' },
    impact_delta: {
      value: 4.8,
      variation_direction: 'up',
      tooltip: 'Volume Contribution: 0.7%',
    },
    impact_growth_rate: { value: 16.2, variation_direction: 'up' },
    impact_post_period: {
      value: 0.7,
      unit_measure: '%',
      variation_direction: 'up',
    },
  },
  brahma: {
    impact_pre_period: { value: 45.2, tooltip: '45,200 hl' },
    impact_delta: {
      value: -6.1,
      variation_direction: 'down',
      tooltip: 'Volume Contribution: -0.9%',
    },
    impact_growth_rate: { value: -13.5, variation_direction: 'down' },
    impact_post_period: {
      value: -0.9,
      unit_measure: '%',
      variation_direction: 'down',
    },
  },
  original: {
    impact_pre_period: { value: 61.8, tooltip: '61,800 hl' },
    impact_delta: {
      value: -7.2,
      variation_direction: 'down',
      tooltip: 'Volume Contribution: -1.1%',
    },
    impact_growth_rate: { value: -11.7, variation_direction: 'down' },
    impact_post_period: {
      value: -1.1,
      unit_measure: '%',
      variation_direction: 'down',
    },
  },
};

