  corona: {
    input_pre_period: { value: 11.8 },
    input_post_period: { value: 13.6 },
    input_delta: { value: 1.8, variation_direction: 'up' },
  },
  stella: {
    input_pre_period: { value: 9.4 },
    input_post_period: { value: 10.1 },
    input_delta: { value: 0.7, variation_direction: 'up' },
  },
