    input_pre_period: { value: 14.3 },
    input_post_period: { value: 16.5 },
    input_delta: { value: 2.2, variation_direction: 'up' },
  },
  spaten: {
    input_pre_period: { value: 8.7 },
    input_post_period: { value: 7.9 },
    input_delta: { value: -0.8, variation_direction: 'down' },
  },
  skol: {
    input_pre_period: { value: 7.2 },
    input_post_period: { value: 8.1 },
    input_delta: { value: 0.9, variation_direction: 'up' },
  },
  brahma: {
    input_pre_period: { value: 10.6 },
    input_post_period: { value: 9.4 },
    input_delta: { value: -1.2, variation_direction: 'down' },
  },
  original: {
    input_pre_period: { value: 12.4 },
    input_post_period: { value: 10.9 },
    input_delta: { value: -1.5, variation_direction: 'down' },
  },
};

const DRIVER_IMPACT_CELLS: Record<string, WatchtowerApiCell | null> = {
  impact_pre_period: { value: 104 },
  impact_delta: { value: 104 },
  impact_growth_rate: { value: 38.9, variation_direction: 'up' },
  impact_post_period: {
    value: 0.49,
    unit_measure: '%',
    variation_direction: 'up',
  },
};

const DRIVER_INPUT_CELLS: Record<string, WatchtowerApiCell | null> = {
  input_pre_period: { value: 105 },
  input_post_period: { value: 105 },
  input_delta: { value: 42.3, variation_direction: 'up' },
};

function getCellNumber(cell?: WatchtowerApiCell | null): number | null {
  if (cell?.value == null) {
    return null;
  }

  if (typeof cell.value === 'number') {
    return cell.value;
  }

  const parsed = Number(cell.value);
  return Number.isNaN(parsed) ? null : parsed;
}

function mapDeltaDirection(
  delta: number,
): WatchtowerApiCell['variation_direction'] {
  if (delta > 0) return 'up';
  if (delta < 0) return 'down';
  return 'neutral';
}

function toMacoRoiCells(
  inputCells: Record<string, WatchtowerApiCell | null>,
): Record<string, WatchtowerApiCell | null> {
  const preInput = getCellNumber(inputCells.input_pre_period);
  const postInput = getCellNumber(inputCells.input_post_period);
  const inputDelta = getCellNumber(inputCells.input_delta);

  if (preInput == null || postInput == null || inputDelta == null) {
    return {
      maco_roi_pre_period: null,
      maco_roi_post_period: null,
      maco_roi_delta: null,
    };
  }

  const macoPre = Number((preInput * 0.82).toFixed(1));
  const macoPost = Number((postInput * 0.86).toFixed(1));
  const macoDelta = Number((inputDelta * 0.78).toFixed(1));

  return {
    maco_roi_pre_period: { value: macoPre },
    maco_roi_post_period: { value: macoPost },
    maco_roi_delta: {
      value: macoDelta,
      variation_direction: mapDeltaDirection(macoDelta),
    },
  };
}

const DRIVERS: Array<{
  id: string;
  label: string;
  hasChildren: boolean;
  tooltip?: string;
}> = [
  {
    id: 'sales-mktg',
    label: 'Sales & Marketing Invest...',
    tooltip: 'Sales & Marketing Investments',
    hasChildren: false,
  },
  { id: 'execution', label: 'Execution', hasChildren: false },
  { id: 'weighted-dist', label: 'Weighted Distribution', hasChildren: true },
  { id: 'simple-dist', label: 'Simple Distribution', hasChildren: false },
