];

function makeBrandSubRows(brandId: string): WatchtowerApiRow[] {
  const rows: WatchtowerApiRow[] = [];

  DRIVERS.forEach((driver) => {
    rows.push({
      id: `${brandId}-${driver.id}`,
      parent_id: brandId,
      level: 1,
      has_children: driver.hasChildren,
      label: driver.label,
      tooltip: driver.tooltip,
      cells: { ...DRIVER_IMPACT_CELLS, ...DRIVER_INPUT_CELLS },
    });
  });

  REGIONS.forEach((region) => {
    rows.push({
      id: `${brandId}-wd-${region.id}`,
      parent_id: `${brandId}-weighted-dist`,
      level: 2,
      has_children: region.id === 'no',
      label: region.label,
      cells: { ...DRIVER_IMPACT_CELLS, ...DRIVER_INPUT_CELLS },
    });
  });

  rows.push(
    {
      id: `${brandId}-wd-no-on-trade`,
      parent_id: `${brandId}-wd-no`,
      level: 3,
      has_children: false,
      label: 'On Trade',
      cells: { ...DRIVER_IMPACT_CELLS, ...DRIVER_INPUT_CELLS },
    },
    {
      id: `${brandId}-wd-no-off-trade`,
      parent_id: `${brandId}-wd-no`,
      level: 3,
      has_children: false,
      label: 'Off Trade',
      cells: { ...DRIVER_IMPACT_CELLS, ...DRIVER_INPUT_CELLS },
    },
  );

  return rows;
}

